document.querySelector('#products').innerHTML = products.map(p=>`<button class="product-card reveal" data-product="${p.id}" aria-label="Scopri ${p.name}"><span class="product-category">${p.category}</span><h3>${p.name}</h3><p>${p.tagline}</p>${p.image?`<div class="product-image"><img src="assets/${p.image}.webp" alt="Rappresentazione illustrativa: ${p.name}" loading="lazy" width="1536" height="1024"></div>`:miniSoftware}<span class="product-action">Scopri come funziona<span class="plus" aria-hidden="true">+</span></span></button>`).join('');
const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
if ('IntersectionObserver' in window && !reducedMotion.matches) {
 document.body.classList.add('motion-ready');
 const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target);}}),{threshold:.08});
 document.querySelectorAll('.reveal').forEach((el,i)=>{if(el.classList.contains('product-card'))el.style.transitionDelay=`${(i%3)*65}ms`;revealObserver.observe(el);});
}
const menuButton=document.querySelector('.menu-toggle'),navigation=document.querySelector('#navigation');
menuButton.addEventListener('click',()=>{const expanded=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(expanded));menuButton.setAttribute('aria-label',expanded?'Chiudi menu':'Apri menu');navigation.classList.toggle('open',expanded);});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{navigation.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Apri menu');}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){navigation.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.focus();}});
const productDialog=document.querySelector('#product-dialog');let activeProduct=null;
function openProduct(id){
 const p=products.find(p=>p.id===id);if(!p)return;activeProduct=p;
 document.querySelector('#dialog-content').innerHTML=`<div class="dialog-layout"><div class="dialog-visual" data-detail="0" data-product-type="${p.id}"><div class="dialog-image">${p.image?`<img src="assets/${p.image}.webp" alt="Rappresentazione illustrativa: ${p.name}" width="1536" height="1024"><div class="detail-beam" aria-hidden="true"></div>`:miniSoftware}</div><p class="dialog-visual-caption">${p.image?'RAPPRESENTAZIONE ILLUSTRATIVA DEL DISPOSITIVO':'ESEMPIO DI FLUSSO OPERATIVO'}</p></div><div class="dialog-copy"><p class="eyebrow">${p.category}</p><h2 id="dialog-title">${p.name}</h2><p class="dialog-subtitle">${p.tagline}</p><div class="detail-tabs" role="tablist" aria-label="Dettagli ${p.name}">${['A cosa serve','Come funziona','Il servizio'].map((label,i)=>`<button role="tab" id="detail-tab-${i}" aria-selected="${i===0}" aria-controls="detail-panel" data-detail="${i}" tabindex="${i===0?0:-1}">${label}</button>`).join('')}</div><div class="detail-panel" id="detail-panel" role="tabpanel" aria-labelledby="detail-tab-0"><h3>${p.purpose}</h3><p>${p.description}</p></div>${p.image?`<button class="dialog-animation-link" data-watch="${p.id}">Guarda l’animazione</button>`:''}<button class="button dark dialog-cta" data-inquiry="${p.id}">Parliamo di ${p.id==='software'?'software':p.name.toLowerCase()}</button></div></div>`;
 productDialog.showModal();document.body.classList.add('dialog-open');
 productDialog.querySelectorAll('[data-detail]').forEach(btn=>{if(btn.tagName==='BUTTON')btn.addEventListener('click',()=>selectDetail(Number(btn.dataset.detail)));});
 setupTabs(productDialog.querySelector('.detail-tabs'),selectDetail);
 const watch=productDialog.querySelector('[data-watch]');if(watch)watch.addEventListener('click',()=>{productDialog.close();scrollToScenario(p.id);});
 productDialog.querySelector('[data-inquiry]').addEventListener('click',()=>{productDialog.close();const select=document.querySelector('#interest');select.value=p.interest;document.querySelector('#contatti').scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth'});setTimeout(()=>document.querySelector('#name').focus({preventScroll:true}),reducedMotion.matches?0:550);});
}
function selectDetail(index){if(!activeProduct)return;const p=activeProduct;
 productDialog.querySelectorAll('[role=tab]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;});
 const panel=productDialog.querySelector('#detail-panel');panel.setAttribute('aria-labelledby',`detail-tab-${index}`);
 const h=[p.purpose,p.howTitle,p.service][index],desc=[p.description,p.how,p.support][index];
 panel.innerHTML=`<h3>${h}</h3><p>${desc}</p>${index===1?`<div class="detail-flow" aria-label="Fasi del funzionamento">${p.flow.map(f=>`<span>${f}</span>`).join('')}</div>`:''}`;
 productDialog.querySelector('.dialog-visual').dataset.detail=String(index);
}
function setupTabs(group,choose){group.addEventListener('keydown',e=>{const tabs=[...group.querySelectorAll('[role=tab]')];const current=tabs.indexOf(document.activeElement);if(current<0)return;let next;if(e.key==='ArrowRight')next=(current+1)%tabs.length;else if(e.key==='ArrowLeft')next=(current-1+tabs.length)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();choose(next);tabs[next].focus();});}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-product]');if(btn)openProduct(btn.dataset.product);});
document.querySelectorAll('dialog').forEach(dialog=>{
 dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open');});
});
const workflowStates=[{heading:'Eventi raccolti',origin:'Dispositivi',task:'Raccolta dati',status:'Acquisito',className:'',footer:'Il dato entra nel sistema.',description:'Organizza gli eventi provenienti dai dispositivi in un unico flusso di lavoro.'},{heading:'Verifica degli eventi',origin:'Dati raccolti',task:'Verifica operatore',status:'Da verificare',className:'verified',footer:'L’operatore controlla le informazioni.',description:'Porta le informazioni all’attenzione dell’operatore per la verifica di ogni evento.'},{heading:'Gestione delle attività',origin:'Eventi verificati',task:'Gestione operativa',status:'In gestione',className:'managed',footer:'Il flusso prosegue nelle attività dell’ufficio.',description:'Accompagna la gestione delle attività con un flusso definito sulle esigenze dell’ente.'}];
function changeWorkflow(index){const state=workflowStates[index];document.querySelectorAll('.workflow-button').forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;});document.querySelector('#workflow-panel').setAttribute('aria-labelledby',`workflow-tab-${index}`);for(const [selector,value]of Object.entries({'#dashboard-heading':state.heading,'#dashboard-origin':state.origin,'#dashboard-task':state.task,'#dashboard-footer':state.footer,'#workflow-description':state.description}))document.querySelector(selector).textContent=value;
 document.querySelectorAll('.status-tag').forEach(t=>{t.textContent=state.status;t.className=`status-tag ${state.className}`;});document.querySelector('.dashboard-progress i').style.width=`${(index+1)/3*100}%`;const win=document.querySelector('.software-window');win.classList.remove('changing');void win.offsetWidth;win.classList.add('changing');}
document.querySelectorAll('[data-workflow]').forEach(b=>b.addEventListener('click',()=>changeWorkflow(Number(b.dataset.workflow))));setupTabs(document.querySelector('.workflow-options'),changeWorkflow);
let framePending=false;
function updateScroll(){framePending=false;updateScrollSimulation();if(reducedMotion.matches)return;
 const hero=document.querySelector('.hero-media');const rect=hero.getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight)hero.querySelector('img').style.transform=`translateY(${Math.max(-24,Math.min(24,(innerHeight/2-rect.top-rect.height/2)*.06))}px) scale(1.13)`;

}
addEventListener('scroll',()=>{if(!framePending){framePending=true;requestAnimationFrame(updateScroll);}},{passive:true});
const emailDialog=document.querySelector('#email-dialog');
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const summary=`Nome: ${data.get('name')}\nE-mail: ${data.get('email')}\n${data.get('phone')?`Telefono: ${data.get('phone')}\n`:''}Esigenza: ${data.get('interest')}\n\n${data.get('message')}`;document.querySelector('#email-summary').textContent=summary;document.querySelector('#email-link').href=`mailto:info@hypnosweb.it?subject=${encodeURIComponent('Richiesta informazioni — '+data.get('interest'))}&body=${encodeURIComponent(summary)}`;emailDialog.showModal();document.body.classList.add('dialog-open');});

if ('IntersectionObserver' in window) { const photoObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('in-view',e.isIntersecting)),{threshold:.1});document.querySelectorAll('.product-card').forEach(card=>photoObserver.observe(card)); }
const scenarios={
 anpr:{title:'Dal passaggio<br> alla lettura della targa.',description:'Il veicolo si avvicina. La telecamera acquisisce l’immagine e riconosce i caratteri della targa. Il dato entra nel flusso operativo.',steps:['Avvicinamento','Acquisizione','Lettura della targa'],phases:['Il veicolo si avvicina.','La telecamera acquisisce la targa.','La targa diventa un dato.'],label:'TARGA RILEVATA',value:'AA 000 AA',meta:'Il dato è pronto per la verifica.'},
 ztl:{title:'Un varco.<br> Un accesso da verificare.',description:'L’auto si avvicina al varco. La targa viene letta e il passaggio entra nella verifica delle autorizzazioni e degli orari previsti dall’ente.',steps:['Ingresso al varco','Lettura targa','Verifica accesso'],phases:['Il veicolo si avvicina al varco.','La targa viene rilevata.','Il passaggio è pronto per la verifica.'],label:'ACCESSO RILEVATO',value:'AA 000 AA',meta:'Da verificare con le autorizzazioni.'},
 autovelox:{title:'La velocità.<br> In un preciso istante.',description:'L’auto raggiunge il punto di controllo. Il dispositivo rileva la velocità al passaggio e registra l’evento per il successivo flusso di verifica.',steps:['Avvicinamento','Rilevazione','Registrazione evento'],phases:['L’auto raggiunge il punto di controllo.','Il dispositivo rileva la velocità.','L’evento entra nel flusso di verifica.'],label:'VELOCITÀ / ESEMPIO',value:'52 km/h',meta:'Rilevazione in un singolo punto.'},
 tutor:{title:'Due passaggi.<br> Una velocità media.',description:'Il sistema registra l’ingresso e l’uscita. Nell’esempio, 500 metri percorsi in 36 secondi corrispondono a una velocità media di 50 km/h.',steps:['Rilevazione ingresso','Percorrenza del tratto','Rilevazione uscita'],phases:['Ingresso registrato: 10:00:00.','Il veicolo percorre il tratto.','Uscita registrata: 10:00:36.'],label:'VELOCITÀ MEDIA / ESEMPIO',value:'50 km/h',meta:'500 m · 36 s · distanza ÷ tempo'},
 parcometri:{title:'L’auto si ferma.<br> La sosta è organizzata.',description:'Il veicolo raggiunge lo stallo. Il cittadino seleziona la durata e paga al parcometro secondo le modalità e le tariffe previste dall’ente.',steps:['Arrivo nello stallo','Selezione durata','Pagamento della sosta'],phases:['Il veicolo raggiunge lo stallo.','Il cittadino seleziona la durata.','La sosta viene pagata.'],label:'SOSTA / ESEMPIO',value:'60 minuti',meta:'Pagamento illustrativo completato.'}
};
const roadScene=document.querySelector('.road-scene'),sceneCar=document.querySelector('.scene-car'),simulationSection=document.querySelector('.simulation-section');
const scenarioOrder=Object.keys(scenarios);let carAnimation=null,scenarioId='anpr',lastPhase=-1;
function updateSimulationPhase(phase){if(phase===lastPhase)return;lastPhase=phase;roadScene.dataset.phase=String(phase);document.querySelector('.scene-phase-number').textContent=String(phase+1).padStart(2,'0');document.querySelector('.scene-phase-text').textContent=scenarios[scenarioId].phases[phase];document.querySelectorAll('.sim-step').forEach((s,i)=>s.classList.toggle('active',i===phase));}
function selectScenario(id){scenarioId=id;const s=scenarios[id];document.querySelectorAll('[data-simulation]').forEach(b=>{const active=b.dataset.simulation===id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});document.querySelector('#simulation-panel').setAttribute('aria-labelledby',`sim-tab-${id}`);document.querySelector('#simulation-title').innerHTML=s.title;document.querySelector('#simulation-description').textContent=s.description;document.querySelectorAll('.sim-step p').forEach((p,i)=>p.textContent=s.steps[i]);document.querySelector('.scene-data-label').textContent=s.label;document.querySelector('.scene-data-value').textContent=s.value;document.querySelector('.scene-data-meta').textContent=s.meta;document.querySelector('#simulation-detail').dataset.product=id;document.querySelector('.simulation-count').textContent=`${String(scenarioOrder.indexOf(id)+1).padStart(2,'0')} / 05`;const device=roadScene.querySelector('.scene-device');device.src=`assets/${id}.webp`;device.alt=products.find(p=>p.id===id).name;roadScene.dataset.scenario=id;
 if(carAnimation)carAnimation.cancel();lastPhase=-1;
 const approach=[{transform:'translate(45%, -25%) scale(.45)',opacity:0,offset:0},{transform:'translate(30%, -17%) scale(.6)',opacity:1,offset:.15},{transform:'translate(0,0) scale(1)',opacity:1,offset:.35},{transform:'translate(0,0) scale(1)',opacity:1,offset:.94},{transform:'translate(-10%,4%) scale(1.04)',opacity:0,offset:1}];
 const crossing=[{transform:'translate(80%, -13%) scale(.8)',opacity:0,offset:0},{transform:'translate(43%, -7%) scale(.85)',opacity:1,offset:.15},{transform:'translate(8%,0) scale(.92)',opacity:1,offset:.35},{transform:'translate(-10%,5%) scale(1)',opacity:1,offset:.55},{transform:'translate(-55%,17%) scale(1)',opacity:1,offset:.72},{transform:'translate(-95%,30%) scale(1)',opacity:0,offset:.94},{transform:'translate(-95%,30%) scale(1)',opacity:0,offset:1}];
 carAnimation=sceneCar.animate(id==='autovelox'||id==='tutor'?crossing:approach,{duration:10000,fill:'both',easing:'linear'});carAnimation.pause();updateSimulationPhase(0);
}
function scrollToScenario(id){if(reducedMotion.matches){selectScenario(id);carAnimation.currentTime=6500;updateSimulationPhase(2);return;}const start=simulationSection.getBoundingClientRect().top+scrollY-100;const distance=simulationSection.offsetHeight-innerHeight;const index=scenarioOrder.indexOf(id);scrollTo({top:start+distance*(index+.06)/5,behavior:'smooth'});}
function updateScrollSimulation(){if(!carAnimation)return;const rect=simulationSection.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight)return;const start=rect.top+scrollY-100;const distance=simulationSection.offsetHeight-innerHeight;const total=Math.max(0,Math.min(.99999,(scrollY-start)/distance));const current=total*5;const index=Math.floor(current);const local=current-index;if(scenarioId!==scenarioOrder[index])selectScenario(scenarioOrder[index]);carAnimation.currentTime=reducedMotion.matches?6500:local*10000;updateSimulationPhase(reducedMotion.matches?2:local<.35?0:local<.62?1:2);document.querySelector('.scroll-progress i').style.width=`${local*100}%`;}
document.querySelectorAll('[data-simulation]').forEach(b=>b.addEventListener('click',()=>scrollToScenario(b.dataset.simulation)));setupTabs(document.querySelector('.simulation-tabs'),i=>scrollToScenario(scenarioOrder[i]));
selectScenario('anpr');updateScrollSimulation();addEventListener('resize',()=>{updateScrollSimulation();},{passive:true});

updateScroll();
